#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import { readFileSync } from 'node:fs'
import { parse, ParseError, Table, ArrayOfTables } from './parser.js'

const mode = process.argv.length === 3 ? process.argv[2] : undefined
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const cmp = (a, b) => {
  const x = Array.from(a)
  const y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function toJson(v, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  let items
  if (v instanceof Table) {
    const ks = sortedKeys(v)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${toJson(v.map.get(k), ind + 1)}`).join(',\n') + `\n${end}}`
  }
  if (v instanceof ArrayOfTables) items = v.items
  else if (v.type === 'array') items = v.items
  else return JSON.stringify(v.value)
  if (!items.length) return '[]'
  return '[\n' + items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + `\n${end}]`
}

function typeOf(v) {
  if (v instanceof Table) return 'table'
  if (v instanceof ArrayOfTables) return 'array'
  return v.type
}

function keys(v, path, out) {
  const kids = []
  if (v instanceof Table) for (const k of sortedKeys(v)) kids.push([path === null ? k : `${path}.${k}`, v.map.get(k)])
  else {
    const items = v instanceof ArrayOfTables ? v.items : v.type === 'array' ? v.items : []
    items.forEach((x, i) => kids.push([`${path}[${i}]`, x]))
  }
  for (const [p, c] of kids) {
    out.push(`${p} ${typeOf(c)}`)
    keys(c, p, out)
  }
}

let root
try {
  root = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
if (mode === 'json') process.stdout.write(toJson(root, 0) + '\n')
else {
  const out = []
  keys(root, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
EOF
